<?php $purchased = $itemsByOrder[$order['id']] ?? []; ?>
<tr class="admin-order-detail-row"><td colspan="7"><details class="admin-order-details"><summary>View purchased items (<?=count($purchased)?>) and delivery details</summary><div class="admin-order-detail-content"><div class="admin-order-purchases"><?php foreach($purchased as $item): ?><div><span><strong><?=e($item['product_name'])?></strong><small>Size <?=e($item['size'])?> · Qty <?=e($item['quantity'])?><?php if($item['custom_name'] || $item['custom_number']): ?> · Custom: <?=e(trim(($item['custom_name']??'').' '.($item['custom_number']??'')))?><?php endif; ?></small></span><b><?=price($item['line_total'])?></b></div><?php endforeach; ?><?php if(!$purchased): ?><p>No item details available.</p><?php endif; ?></div><div class="admin-order-delivery"><strong>Delivery</strong><span><?=e($order['customer_name'])?> · <?=e($order['phone'])?></span><span><?=e($order['address'])?></span><?php if($order['township'] || $order['city']): ?><span><?=e(trim(($order['township']??'').' '.($order['city']??'')))?></span><?php endif; ?><?php if($order['note']): ?><small>Note: <?=e($order['note'])?></small><?php endif; ?></div></div></details></td></tr>
